html:
{% if doc.payment_type=="Pay" %}

<style>
   
    @page {
        margin-top: 20px;
    }

    
    @media screen {
        .print-format {
            width: 9.4in;
            padding: 0.20in;
            min-height: 11.7in;
        }
    }
    .print-format p{
    margin:1px 0;
    line-height:1.1;
}
    

</style>
<div id="header-html" style="height:10px;">
    <div class="header-img"></div>
</div>

{% set logo = frappe.db.get_value("Orion Settings", None, "company_logo") %}
{% set company_tax_id = frappe.db.get_value("Company",doc.company,'tax_id') %}
{% set company_address = frappe.db.sql("""select a.address_line1, a.address_line2,a.city,a.phone,a.email_id from 
`tabAddress` a inner join `tabDynamic Link` dl on dl.parent=a.name
where dl.link_doctype='Company'
and dl.link_name=%s
limit 1
""",(doc.company),as_dict=1) %}

{% set party_address_name = frappe.db.get_value(
"Dynamic Link",
{
"link_doctype":doc.party_type,
"link_name":doc.party,
"parenttype":"Address"
},
"parent"
) %}

{% set party_address = frappe.db.get_value(
"Address",
party_address_name,
[
"address_line1",
"address_line2",
"city",
],
as_dict=True
) %}
{% set customer_tax_id = frappe.db.get_value("Customer",doc.party,'tax_id') %}
<table style="width:100%;margin-bottom:40px;">
<tr>

<td style="width:50%;vertical-align:top;">

<table style="width:100%; border-collapse:collapse; margin-bottom:30px;">
    <tr>
        <!-- Logo -->
        <td style="width:25%; vertical-align:middle;">
            {% if logo %}
            <img src="{{ logo }}" style="height:55px;">
            {% endif %}
        </td>

        <!-- Title -->
        <td style="width:68%; text-align:right; vertical-align:middle;">
            <div style="font-size:25px; font-weight:700; color:#1a1a1a; letter-spacing:-0.5px;margin-top:20px">
                Payment Voucher
            </div>
        </td>
    </tr>
</table>

<table style="width:100%; border-collapse:collapse; border-spacing:0; font-size:10px;">
<tr>


<td width="30%" style="vertical-align:top; padding-right:8px;">


<p style="margin:0 0 6px 0; font-weight:bold; text-transform:uppercase;font-size:9px;margin-top:-20px">
{{ doc.company }}
</p>

{% if company_address and company_address[0] %}
{% set addr = company_address[0] %}
<p style="margin:0 0 4px 0; font-size:9px;">
    {{ addr.address_line1 or "" }}<br>
    {% if addr.address_line2 %}{{ addr.address_line2 }}<br>{% endif %}
    {{ addr.city or "" }}<br>
    {{ addr.country or "" }}
    {% if addr.pincode %} - {{ addr.pincode }}{% endif %}

    {% if addr.phone %}
    Phone: {{ addr.phone }}<br>
    {% endif %}

    {% if addr.email_id %}
    Email: {{ addr.email_id }}
    {% endif %}
</p>
{% endif %}

{% if company_trn %}
<p style="margin:0; font-weight:bold;">
TRN : {{ company_trn }}
</p>
{% endif %}

</td>



</tr>
</table>

<table style="width:100%;margin-top:15px;border-collapse:collapse;">
<tr>

<td style="width:58%;vertical-align:top;font-size:9px;color:#444;">

<div style="margin-bottom:3px;">
    <span style="display:inline-block;width:125px;">Payment No.#</span>
    <span style="display:inline-block;width:12px;">:</span>
    <span style="font-weight:bold;color:#111;">{{ doc.name }}</span>
</div>

<div style="margin-bottom:3px;">
    <span style="display:inline-block;width:125px;">Payment Date</span>
    <span style="display:inline-block;width:12px;">:</span>
    <span style="font-weight:bold;color:#111;">
        {{ frappe.utils.formatdate(doc.posting_date,"dd MMM yyyy") }}
    </span>
</div>

<div style="margin-bottom:3px;">
    <span style="display:inline-block;width:125px;">Reference Number</span>
    <span style="display:inline-block;width:12px;">:</span>
    <span style="font-weight:bold;color:#111;">
        {{ doc.reference_no or "" }}
    </span>
</div>

<div style="margin-bottom:3px;">
    <span style="display:inline-block;width:125px;">Payment Mode</span>
    <span style="display:inline-block;width:12px;">:</span>
    <span style="font-weight:bold;color:#111;">
        {{ doc.mode_of_payment }}
    </span>
</div>

<div>
    <span style="display:inline-block;width:125px;">Paid Through</span>
    <span style="display:inline-block;width:12px;">:</span>
    <span style="font-weight:bold;color:#111;">
        {{ doc.paid_to.split('-')[0] if doc.paid_to else "" }}
    </span>
</div>

</td>


<td style="width:42%;vertical-align:top;text-align:center;">

<div style="
                background:#2f834a;
                width:210px;
                height:70px;
                margin-left:auto;
                margin-right:0;
                margin-top:-10px;
                color:#fff;
                padding-top:12px;
            ">

                <div style="
                    font-size:9px;
                    font-weight:bold;
                    margin-bottom:10px;
                    color:#fff;
                ">
                    Amount Received
                </div>

                <div style="
                    font-size:18px;
                    font-weight:bold;
                    white-space:nowrap;
                    color:#fff;
                ">
                    AED {{ "{:,.2f}".format(doc.paid_amount) }}
                </div>

            </div>


</td>

</tr>
</table>

<!-- RECEIVED FROM -->
<div style="
    margin-top:30px;
">
    <div style="
        background:#2f7f4f;
        color:#fff;
        display:inline-block;
        padding:7px 8px;
        font-size:12px;
        font-weight:bold;
        margin-bottom:12px;
    ">
        Paid To
    </div>

    <div style="
        font-size:9px;
        font-weight:bold;
        color:#111;
        text-transform:uppercase;
        margin-top:8px;
    ">
        {{ doc.party_name }}
    </div>

    <div style="
        font-size:9px;
        color:#444;
        line-height:1.45;
        margin-top:3px;
    ">

        {% if party_address %}
            {{ party_address.address_line1 or "" }}<br>

            {% if party_address.address_line2 %}
                {{ party_address.address_line2 }}<br>
            {% endif %}

            {{ party_address.city or "" }}
        {% endif %}

    </div>
    {% set supplier_tax_id = frappe.db.get_value("Supplier",doc.party,'tax_id') %}
    {% if supplier_tax_id %}
    <div style="
        margin-top:6px;
        font-size:9px;
        font-weight:bold;
        color:#111;
    ">
        TRN : {{ supplier_tax_id }}
    </div>
    {% endif %}

</div>
<div style="
font-size:12px;
font-weight:bold;
color:#2f7d4b;
text-decoration:underline;
margin-top:35px;
margin-bottom:12px;
">
Payment For
</div>

<table style="width:100%;border-collapse:collapse;font-size:10px;">

<tr style="background:#2f7d4b;font-weight:bold;color:#fff;">
    <td style="padding:9px 12px;color:#fff;">Bill Number</td>
    <td style="padding:9px 12px;color:#fff;">Bill Date</td>
    <td style="padding:9px 12px;text-align:right;color:#fff;">Bill Amount</td>
    <td style="padding:9px 12px;text-align:right;color:#fff;">Payment Amount</td>
</tr>

{% set ns=namespace(total_payment_amount=0) %}

{% for row in doc.references %}

    {% set ref_doc = frappe.get_doc(row.reference_doctype,row.reference_name) %}

    {% set ref_date = ref_doc.posting_date or ref_doc.transaction_date or ref_doc.creation %}

    {% set ref_amount =
        ref_doc.grand_total
        or ref_doc.total_amount
        or ref_doc.advance_amount
        or row.total_amount
        or row.allocated_amount
    %}

    {% set ns.total_payment_amount = ns.total_payment_amount + (row.allocated_amount or 0) %}

    <tr style="background:{% if loop.index % 2 == 0 %}#edf2ee{% else %}#ffffff{% endif %};">

        <td style="padding:7px 12px;">
            {{ row.reference_name }}
        </td>

        <td style="padding:7px 12px;">
            {{ frappe.utils.formatdate(ref_date,"dd MMM yyyy") }}
        </td>

        <td style="padding:7px 12px;text-align:right;">
            {{ "{:,.2f}".format(ref_amount) }} AED
        </td>

        <td style="padding:7px 12px;text-align:right;">
            {{ "{:,.2f}".format(row.allocated_amount) }} AED
        </td>

    </tr>

{% endfor %}

<tr style="background:#2f7d4b;font-weight:bold;color:#fff;">

    <td style="padding:10px 12px;color:#fff;">
        Total
    </td>

    <td></td>

    <td></td>

    <td style="padding:10px 12px;text-align:right;color:#fff;">
        {{ "{:,.2f}".format(ns.total_payment_amount) }} AED
    </td>

</tr>

</table>

<div id="footer-html" class="visible-pdf" style="width:100%; padding:0 10px;">
    <div style="border-top: 1.5px dashed #2f6b3c; margin-bottom: 8px; width: 100%;"></div>
    
    <table style="width:100%; font-size:8px; border-collapse:collapse; line-height:1.3;">
        <tr>
            <!-- PO Number Column -->
            <td style="width:8%; padding:2px 0; vertical-align:top; border:none;">
                <span style="color:#555555; display:block;white-space:nowrap;">Payment No.#</span>
                <span style="font-weight:700; color:#000000;white-space:nowrap;">{{ doc.name }}</span>
            </td>
            
            <!-- Date Column -->
            <td style="width:8%; padding:2px 0; vertical-align:top; border:none;">
                <span style="color:#555555; display:block;white-space:nowrap;">Payment Date</span>
                <span style="font-weight:700; color:#000000;white-space:nowrap;">{{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}</span>
            </td>
            
            <!-- Vendor Column -->
            <td style="width:55%; padding:2px 0; vertical-align:top; border:none;">
                <span style="color:#555555; display:block;white-space:nowrap;">Paid To</span>
                <span style="font-weight:700; color:#000000;white-space:nowrap; text-transform:uppercase;">{{ doc.party_name }}</span>
            </td>
            
            <!-- Page Number Column -->
            <td style="width:15%; padding:2px 0; vertical-align:middle; text-align:right; border:none; font-weight:700; color:#000000;">
                Page <span class="page"></span> of <span class="topage"></span>
            </td>
        </tr>
    </table>
    
    <div style="text-align:center; font-size:8px; color:#666666; margin-top:8px;">
        This is a computer-generated document and is deemed to be signed.
    </div>
</div>
{% else %}
This Print format is for Payment Type = Pay.
{% endif %}
